  1	/**
  2	 * New issue page; blocked at the per-project issue quota.
  3	 *
  4	 * Owner D. `issuesPerProject` counts archived issues too, so an org that has
  5	 * filled a project cannot make room by archiving — that is deliberate, and the
  6	 * copy below says so rather than leaving people to guess.
  7	 *
  8	 * Must call (do not reimplement): can, getPlanLimits
  9	 */
 10	
 11	import Link from "next/link";
 12	import { notFound } from "next/navigation";
 13	import type { Metadata } from "next";
 14	import { createIssueAction } from "@/actions/issues/create-issue";
 15	import { PENDING_ISSUE_ID } from "@/actions/_lib/permission-resources";
 16	import { IssueForm } from "@/components/domain/issue/issue-form";
 17	import { getPlanLimits } from "@/config/plan-limits";
 18	import { can } from "@/lib/permissions";
 19	import { issueStatusSchema } from "@/schemas/issue";
 20	import { listIssues } from "@/server/services/issue-service";
 21	import { listLabels } from "@/server/services/label-service";
 22	import { listMembers } from "@/server/services/member-service";
 23	import type { IssueStatus } from "@/types/issue";
 24	import { loadProjectContext } from "../../../../_lib/project-context";
 25	
 26	type PageParams = { orgSlug: string; projectSlug: string };
 27	
 28	export const dynamic = "force-dynamic";
 29	
 30	export const metadata: Metadata = {
 31	  title: "New issue",
 32	};
 33	
 34	const MEMBER_PICKER_LIMIT = 100;
 35	
 36	export default async function Page(props: {
 37	  params: Promise<PageParams>;
 38	  searchParams: Promise<Record<string, string | string[] | undefined>>;
 39	}) {
 40	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
 41	  const { orgSlug, projectSlug } = await props.params;
 42	  await props.searchParams;
 43	
 44	  const { org, actor, project } = await loadProjectContext(orgSlug, projectSlug);
 45	
 46	  const allowed = can(actor, "issue:create", {
 47	    kind: "issue",
 48	    orgId: org.id,
 49	    projectId: project.id,
 50	    issueId: PENDING_ISSUE_ID,
 51	    authorId: actor.userId,
 52	    assigneeId: null,
 53	  });
 54	  if (!allowed) {
 55	    notFound();
 56	  }
 57	
 58	  const limits = getPlanLimits(org.plan);
 59	  const existing = await listIssues(actor, {
 60	    orgId: org.id,
 61	    projectId: project.id,
 62	    limit: 1,
 63	    includeArchived: true,
 64	  });
 65	
 66	  if (existing.total >= limits.issuesPerProject) {
 67	    return (
 68	      <div className="max-w-lg space-y-4">
 69	        <h1 className="text-xl font-semibold tracking-tight">
 70	          This project is full
 71	        </h1>
 72	        <p className="text-sm text-slate-600">
 73	          The {org.plan} plan allows {limits.issuesPerProject} issues per
 74	          project, archived ones included, and {existing.total} exist. Upgrading
 75	          raises the ceiling; a new project starts with a fresh one.
 76	        </p>
 77	        <div className="flex gap-4 text-sm">
 78	          <Link
 79	            href={`/${orgSlug}/projects/${projectSlug}/issues`}
 80	            className="text-slate-600"
 81	          >
 82	            Back to issues
 83	          </Link>
 84	          <Link href={`/${orgSlug}/settings/billing`} className="text-indigo-600">
 85	            See plans
 86	          </Link>
 87	        </div>
 88	      </div>
 89	    );
 90	  }
 91	
 92	  const [members, labels] = await Promise.all([
 93	    listMembers(actor, { orgId: org.id, limit: MEMBER_PICKER_LIMIT }),
 94	    listLabels(actor, org.id),
 95	  ]);
 96	
 97	  return (
 98	    <div className="max-w-2xl space-y-8">
 99	      <header>
100	        <h1 className="text-2xl font-semibold tracking-tight">New issue</h1>
101	        <p className="mt-1 text-sm text-slate-600">
102	          In {project.name} · {existing.total} of {limits.issuesPerProject} used
103	        </p>
104	      </header>
105	
106	      <IssueForm
107	        orgId={org.id}
108	        projectId={project.id}
109	        members={members.items}
110	        labels={labels}
111	        defaultValues={{
112	          orgId: org.id,
113	          projectId: project.id,
114	          status: defaultStatusFor(org.settings.defaultIssueStatus),
115	        }}
116	        onSubmit={createIssueAction}
117	      />
118	    </div>
119	  );
120	}
121	
122	/**
123	 * `OrganizationSettings.defaultIssueStatus` is stored as a plain string, so it
124	 * is re-validated against the enum before it seeds the form.
125	 */
126	function defaultStatusFor(stored: string): IssueStatus {
127	  const parsed = issueStatusSchema.safeParse(stored);
128	  return parsed.success ? parsed.data : "backlog";
129	}
  1	"use client";
  2	
  3	/**
  4	 * Create/edit form bound to `createIssueSchema` through `zodResolver`.
  5	 *
  6	 * The schema is the same object the Server Action re-parses, so a field the
  7	 * client accepts can never be one the server rejects — that shared definition
  8	 * is the whole point of keeping the Zod schemas outside both layers.
  9	 *
 10	 * Must call (do not reimplement): createIssueSchema
 11	 */
 12	import { zodResolver } from "@hookform/resolvers/zod";
 13	import { useForm, useWatch } from "react-hook-form";
 14	import { Button } from "@/components/ui/button";
 15	import { ErrorMessage } from "@/components/ui/error-message";
 16	import { FormField } from "@/components/ui/form-field";
 17	import { Input } from "@/components/ui/input";
 18	import { Textarea } from "@/components/ui/textarea";
 19	import { useFormAction } from "@/hooks/use-form-action";
 20	import { createIssueSchema, type CreateIssueInput } from "@/schemas/issue";
 21	import type { ActionResult } from "@/types/api";
 22	import type { IsoTimestamp, LabelId, OrgId, ProjectId, UserId } from "@/types/common";
 23	import type { Issue, IssueLabel } from "@/types/issue";
 24	import type { MemberWithUser } from "@/types/member";
 25	import type { ReactElement } from "react";
 26	import { IssueAssigneePicker } from "./issue-assignee-picker";
 27	import { IssueDueDateField } from "./issue-due-date-field";
 28	import { IssueLabelPicker } from "./issue-label-picker";
 29	import { IssuePrioritySelect } from "./issue-priority-select";
 30	import { IssueStatusSelect } from "./issue-status-select";
 31	
 32	export type IssueFormProps = {
 33	  orgId: OrgId;
 34	  projectId: ProjectId;
 35	  defaultValues?: Partial<CreateIssueInput>;
 36	  members: readonly MemberWithUser[];
 37	  labels: readonly IssueLabel[];
 38	  onSubmit: (input: CreateIssueInput) => Promise<ActionResult<Issue>>;
 39	};
 40	
 41	export function IssueForm(props: IssueFormProps): ReactElement | null {
 42	  const { orgId, projectId, defaultValues, members, labels, onSubmit } = props;
 43	
 44	  const form = useForm({
 45	    resolver: zodResolver(createIssueSchema),
 46	    defaultValues: {
 47	      orgId,
 48	      projectId,
 49	      title: "",
 50	      description: null,
 51	      status: "backlog",
 52	      priority: "none",
 53	      assigneeId: null,
 54	      parentId: null,
 55	      estimate: null,
 56	      dueAt: null,
 57	      labelIds: [],
 58	      ...defaultValues,
 59	    },
 60	  });
 61	
 62	  const { submit, pending, error } = useFormAction(onSubmit, {
 63	    onSuccess: () => form.reset(),
 64	  });
 65	
 66	  const values = useWatch({ control: form.control });
 67	  const fieldError = (name: keyof CreateIssueInput): string | null =>
 68	    form.formState.errors[name]?.message ?? null;
 69	
 70	  return (
 71	    <form
 72	      className="space-y-4"
 73	      onSubmit={form.handleSubmit((input) => submit(input))}
 74	    >
 75	      <FormField
 76	        name="title"
 77	        label="Title"
 78	        required
 79	        error={fieldError("title")}
 80	      >
 81	        <Input
 82	          name="title"
 83	          value={values.title ?? ""}
 84	          placeholder="Something is broken"
 85	          invalid={fieldError("title") !== null}
 86	          onChange={(value) => form.setValue("title", value)}
 87	        />
 88	      </FormField>
 89	
 90	      <FormField name="description" label="Description">
 91	        <Textarea
 92	          name="description"
 93	          rows={6}
 94	          value={values.description ?? ""}
 95	          placeholder="What happened, and what did you expect?"
 96	          onChange={(value) =>
 97	            form.setValue("description", value.length === 0 ? null : value)
 98	          }
 99	        />
100	      </FormField>
101	
102	      <div className="grid gap-4 sm:grid-cols-2">
103	        <FormField name="status" label="Status">
104	          <IssueStatusSelect
105	            value={values.status ?? "backlog"}
106	            onChange={(status) => form.setValue("status", status)}
107	          />
108	        </FormField>
109	
110	        <FormField name="priority" label="Priority">
111	          <IssuePrioritySelect
112	            value={values.priority ?? "none"}
113	            onChange={(priority) => form.setValue("priority", priority)}
114	          />
115	        </FormField>
116	
117	        <FormField name="assigneeId" label="Assignee">
118	          <IssueAssigneePicker
119	            value={(values.assigneeId ?? null) as UserId | null}
120	            members={members}
121	            onChange={(userId) => form.setValue("assigneeId", userId)}
122	          />
123	        </FormField>
124	
125	        <FormField name="dueAt" label="Due date">
126	          <IssueDueDateField
127	            value={(values.dueAt ?? null) as IsoTimestamp | null}
128	            onChange={(dueAt) => form.setValue("dueAt", dueAt)}
129	          />
130	        </FormField>
131	      </div>
132	
133	      <FormField name="labelIds" label="Labels">
134	        <IssueLabelPicker
135	          value={(values.labelIds ?? []) as unknown as readonly LabelId[]}
136	          labels={labels}
137	          onChange={(labelIds) => form.setValue("labelIds", [...labelIds])}
138	        />
139	      </FormField>
140	
141	      <ErrorMessage message={error?.message ?? null} />
142	
143	      <Button type="submit" loading={pending} disabled={pending}>
144	        Create issue
145	      </Button>
146	    </form>
147	  );
148	}
  1	"use server";
  2	
  3	/**
  4	 * Creates an issue after the per-project quota check.
  5	 *
  6	 * Owner D. The quota is read from `@/config/plan-limits` rather than hard-coded
  7	 * here — the plan of the owning organization decides `issuesPerProject`.
  8	 *
  9	 * Must call (do not reimplement): createIssueSchema, can, getPlanLimits,
 10	 * getActor, toActionResult
 11	 */
 12	
 13	import { withAction } from "@/actions/_lib/with-action";
 14	import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
 15	import { getPlanLimits } from "@/config/plan-limits";
 16	import { issueTag, orgTag, projectTag, revalidateTagged, CACHE_PROFILES } from "@/lib/cache";
 17	import { can } from "@/lib/permissions";
 18	import { createIssueSchema, type CreateIssueInput } from "@/schemas/issue";
 19	import { createIssue, listIssues } from "@/server/services/issue-service";
 20	import { getOrganizationSummary } from "@/server/services/organization-service";
 21	import type { ActionResult } from "@/types/api";
 22	import type { Issue } from "@/types/issue";
 23	import type { Actor } from "@/types/member";
 24	
 25	const run = withAction<typeof createIssueSchema, Issue>(
 26	  createIssueSchema,
 27	  async (raw, actor) => {
 28	    const input = raw as CreateIssueInput;
 29	
 30	    const allowed = can(actor, "issue:create", {
 31	      kind: "issue",
 32	      orgId: input.orgId,
 33	      projectId: input.projectId,
 34	      issueId: "" as Issue["id"],
 35	      authorId: actor.userId,
 36	      assigneeId: input.assigneeId,
 37	    });
 38	    if (!allowed) {
 39	      throw new ForbiddenActionError("issue:create");
 40	    }
 41	
 42	    await assertProjectHasRoom(actor, input);
 43	
 44	    const issue = await createIssue(actor, input);
 45	
 46	    revalidateTagged(
 47	      [orgTag(input.orgId), projectTag(input.projectId), issueTag(issue.id)],
 48	      CACHE_PROFILES.minutes,
 49	    );
 50	    return issue;
 51	  },
 52	  { revalidate: ["issues"], cacheProfile: "minutes" },
 53	);
 54	
 55	/**
 56	 * Counts the issues already living in the project and compares them with the
 57	 * plan's `issuesPerProject` ceiling. Archived issues still occupy the quota,
 58	 * which is why the count deliberately includes them.
 59	 */
 60	async function assertProjectHasRoom(
 61	  actor: Actor,
 62	  input: CreateIssueInput,
 63	): Promise<void> {
 64	  const summary = await getOrganizationSummary(actor, input.orgId);
 65	  const limits = getPlanLimits(summary.organization.plan);
 66	
 67	  const existing = await listIssues(actor, {
 68	    orgId: input.orgId,
 69	    projectId: input.projectId,
 70	    limit: 1,
 71	    includeArchived: true,
 72	  });
 73	
 74	  if (existing.total >= limits.issuesPerProject) {
 75	    throw new PlanLimitError("issuesPerProject", limits.issuesPerProject, existing.total);
 76	  }
 77	}
 78	
 79	export async function createIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
 80	  return run(raw);
 81	}
  1	/**
  2	 * Wrapper shared by every Server Action: parses with a Zod schema, resolves the
  3	 * `Actor`, maps thrown domain errors to an `AppErrorShape` and revalidates the
  4	 * affected tags.
  5	 *
  6	 * Owner D. Every mutation in `src/actions/**` funnels through here so the four
  7	 * things each one must do — validate, authenticate, translate errors,
  8	 * revalidate — happen in exactly one place.
  9	 *
 10	 * Must call (do not reimplement): getActor, toActionResult, revalidateTagged
 11	 */
 12	
 13	import { getActor, requireActorFor } from "@/lib/actor";
 14	import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
 15	import { toActionResult } from "@/lib/errors";
 16	import { getSessionPrincipal } from "@/lib/session";
 17	import type { ActionResult } from "@/types/api";
 18	import type { OrgId } from "@/types/common";
 19	import type { Actor } from "@/types/member";
 20	import type { ZodType } from "zod";
 21	import { UnauthorizedActionError } from "./action-errors";
 22	
 23	/** The body of an action: already-validated input plus the resolved principal. */
 24	export type ActionHandler = (input: unknown, actor: Actor) => Promise<unknown>;
 25	
 26	export type ActionOptions = {
 27	  /**
 28	   * When `true` (the default) the organization is taken from the parsed input —
 29	   * either an `orgSlug` or an `orgId` field. When `false` the action does not
 30	   * name an organization and the session's active org is used instead.
 31	   */
 32	  requireOrg?: boolean;
 33	  /** Static cache tags invalidated once the handler resolves. */
 34	  revalidate?: readonly string[];
 35	  /** cacheLife profile handed to `revalidateTag` — required in Next 16. */
 36	  cacheProfile?: string;
 37	};
 38	
 39	type OrgBearingInput = { orgSlug?: unknown; orgId?: unknown };
 40	
 41	/**
 42	 * Resolves the actor for one action call.
 43	 *
 44	 * `getActor(orgSlug)` is the primary path because most mutations are dispatched
 45	 * from a `[orgSlug]` route; actions whose payload carries the branded `orgId`
 46	 * instead resolve through `requireActorFor()`.
 47	 */
 48	async function resolveActorFor(input: unknown, fromInput: boolean): Promise<Actor> {
 49	  if (fromInput && typeof input === "object" && input !== null) {
 50	    const record = input as OrgBearingInput;
 51	    if (typeof record.orgSlug === "string" && record.orgSlug.length > 0) {
 52	      return getActor(record.orgSlug);
 53	    }
 54	    if (typeof record.orgId === "string" && record.orgId.length > 0) {
 55	      return requireActorFor(record.orgId as OrgId);
 56	    }
 57	  }
 58	
 59	  const principal = await getSessionPrincipal();
 60	  if (principal === null || principal.activeOrgId === null) {
 61	    throw new UnauthorizedActionError();
 62	  }
 63	  return requireActorFor(principal.activeOrgId);
 64	}
 65	
 66	/** Adds the monotonic token `useActionState` uses to tell two results apart. */
 67	function stamp<T>(result: ActionResult<T>): ActionResult<T> {
 68	  const submittedAt = new Date().toISOString();
 69	  return result.ok
 70	    ? { ok: true, data: result.data, submittedAt }
 71	    : { ok: false, error: result.error, submittedAt };
 72	}
 73	
 74	export function withAction<TSchema extends ZodType, TData>(
 75	  schema: TSchema,
 76	  handler: ActionHandler,
 77	  options: ActionOptions = {},
 78	): (raw: unknown) => Promise<ActionResult<TData>> {
 79	  return async function runAction(raw: unknown): Promise<ActionResult<TData>> {
 80	    const parsed = schema.safeParse(raw);
 81	    if (!parsed.success) {
 82	      return stamp(toActionResult(parsed.error));
 83	    }
 84	
 85	    try {
 86	      const actor = await resolveActorFor(parsed.data, options.requireOrg !== false);
 87	      const data = (await handler(parsed.data, actor)) as TData;
 88	
 89	      const tags = options.revalidate ?? [];
 90	      if (tags.length > 0) {
 91	        revalidateTagged(tags, options.cacheProfile ?? CACHE_PROFILES.minutes);
 92	      }
 93	
 94	      return stamp({ ok: true, data });
 95	    } catch (error) {
 96	      return stamp(toActionResult(error));
 97	    }
 98	  };
 99	}
  1	/**
  2	 * Error types raised by Server Actions that are *expected* failures rather
  3	 * than bugs. Each one carries the `ErrorCode` that `toAppError()` maps into
  4	 * the `AppErrorShape` the client form layer renders, mirroring the convention
  5	 * already used by `PermissionDeniedError` and `TenantScopeError`.
  6	 *
  7	 * These live in `src/actions/_lib` because only the action layer produces
  8	 * them — services throw their own domain errors, and repositories throw none.
  9	 */
 10	
 11	import type { LimitedResource } from "@/types/billing";
 12	import type { IsoTimestamp } from "@/types/common";
 13	import type { PermissionAction } from "@/types/permission";
 14	
 15	/** No session at all, or a session whose active organization is gone. */
 16	export class UnauthorizedActionError extends Error {
 17	  readonly code = "unauthorized" as const;
 18	
 19	  constructor(message = "Sign in to continue.") {
 20	    super(message);
 21	    this.name = "UnauthorizedActionError";
 22	  }
 23	}
 24	
 25	/**
 26	 * `can()` returned false. Distinct from `PermissionDeniedError` (thrown by
 27	 * `assertCan()` inside services) only in that the action layer already knows
 28	 * the action name and does not need the full `PermissionDecision`.
 29	 */
 30	export class ForbiddenActionError extends Error {
 31	  readonly code = "forbidden" as const;
 32	
 33	  constructor(readonly action: PermissionAction) {
 34	    super(`Permission denied: ${action}`);
 35	    this.name = "ForbiddenActionError";
 36	  }
 37	}
 38	
 39	/** A plan quota from `@/config/plan-limits` would be breached. */
 40	export class PlanLimitError extends Error {
 41	  readonly code = "plan_limit_exceeded" as const;
 42	
 43	  constructor(
 44	    readonly resource: LimitedResource,
 45	    readonly limit: number,
 46	    readonly used: number,
 47	  ) {
 48	    super(`Plan limit reached for ${resource}: ${used}/${limit}`);
 49	    this.name = "PlanLimitError";
 50	  }
 51	}
 52	
 53	/** The token bucket in `@/lib/rate-limit` refused the request. */
 54	export class RateLimitedError extends Error {
 55	  readonly code = "rate_limited" as const;
 56	
 57	  constructor(
 58	    readonly bucketKey: string,
 59	    readonly resetAt: IsoTimestamp,
 60	  ) {
 61	    super(`Rate limit exceeded for ${bucketKey}; retry after ${resetAt}`);
 62	    this.name = "RateLimitedError";
 63	  }
 64	}
 65	
 66	/** A feature flag that gates the whole action is off for this organization. */
 67	export class FeatureUnavailableError extends Error {
 68	  readonly code = "forbidden" as const;
 69	
 70	  constructor(readonly flag: string) {
 71	    super(`Feature not available: ${flag}`);
 72	    this.name = "FeatureUnavailableError";
 73	  }
 74	}
 75	
 76	/** The row the action addresses does not exist inside the actor's tenant. */
 77	export class ActionNotFoundError extends Error {
 78	  readonly code = "not_found" as const;
 79	
 80	  constructor(readonly what: string) {
 81	    super(`Not found: ${what}`);
 82	    this.name = "ActionNotFoundError";
 83	  }
 84	}
  1	/**
  2	 * Placeholder branded ids for `can()` calls about rows that do not exist yet.
  3	 *
  4	 * `PermissionResource` is a closed discriminated union, so asking "may this
  5	 * actor create an issue in this project?" still has to name an `issueId`. The
  6	 * ownership escalations inside `can()` compare ids for equality, and an empty
  7	 * string never matches a real ULID — so a create check falls through to the
  8	 * role matrix, which is exactly the intent.
  9	 */
 10	
 11	import type {
 12	  CommentId,
 13	  IssueId,
 14	  MemberId,
 15	  OrgId,
 16	  ProjectId,
 17	} from "@/types/common";
 18	
 19	export const PENDING_ISSUE_ID = "" as IssueId;
 20	export const PENDING_PROJECT_ID = "" as ProjectId;
 21	export const PENDING_COMMENT_ID = "" as CommentId;
 22	export const PENDING_MEMBER_ID = "" as MemberId;
 23	
 24	/**
 25	 * Bucket owner for rate limits consumed before any tenant is known — the login
 26	 * and password-reset flows, which are reachable without a session.
 27	 */
 28	export const ANONYMOUS_ORG_ID = "" as OrgId;

