 25	/**
 26	 * `can()` returned false. Distinct from `PermissionDeniedError` (thrown by
 27	 * `assertCan()` inside services) only in that the action layer already knows
 28	 * the action name and does not need the full `PermissionDecision`.
 29	 */
 30	export class ForbiddenActionError extends Error {
 31	  readonly code = "forbidden" as const;
 32	
 33	  constructor(readonly action: PermissionAction) {
 34	    super(`Permission denied: ${action}`);
 35	    this.name = "ForbiddenActionError";
 36	  }
