 53	/** The token bucket in `@/lib/rate-limit` refused the request. */
 54	export class RateLimitedError extends Error {
 55	  readonly code = "rate_limited" as const;
 56	
 57	  constructor(
 58	    readonly bucketKey: string,
 59	    readonly resetAt: IsoTimestamp,
 60	  ) {
 61	    super(`Rate limit exceeded for ${bucketKey}; retry after ${resetAt}`);
 62	    this.name = "RateLimitedError";
 63	  }
 64	}
 65	
 66	/** A feature flag that gates the whole action is off for this organization. */
 67	export class FeatureUnavailableError extends Error {
 68	  readonly code = "forbidden" as const;
 69	
 70	  constructor(readonly flag: string) {
 71	    super(`Feature not available: ${flag}`);
 72	    this.name = "FeatureUnavailableError";
 73	  }
 74	}
 75	
 76	/** The row the action addresses does not exist inside the actor's tenant. */
 77	export class ActionNotFoundError extends Error {
 78	  readonly code = "not_found" as const;
 79	
 80	  constructor(readonly what: string) {
 81	    super(`Not found: ${what}`);
 82	    this.name = "ActionNotFoundError";
