  3	/**
  4	 * Bridges react-hook-form submission to a Server Action's `ActionResult`.
  5	 *
  6	 * Actions never throw for expected failures — they return
  7	 * `{ ok: false, error }` so the form can render field errors without an error
  8	 * boundary. This hook keeps that contract in one place: expected failures land
  9	 * in `error`, and anything that genuinely throws is normalised by
 10	 * `toAppError()` so the caller only ever sees an `AppErrorShape`.
 11	 */
 12	import { useCallback, useEffect, useRef, useState } from "react";
 13	import { toAppError } from "@/lib/errors";
 14	import type { ActionResult, AppErrorShape } from "@/types/api";
 15	
 16	export type FormActionOptions = {
 17	  onSuccess?: () => void;
 18	  onError?: (error: AppErrorShape) => void;
 19	  resetOnSuccess?: boolean;
 20	};
 21	
 22	export function useFormAction<TInput, TData>(
 23	  action: (input: TInput) => Promise<ActionResult<TData>>,
 24	  options?: FormActionOptions,
 25	): {
 26	  submit: (input: TInput) => Promise<void>;
 27	  pending: boolean;
 28	  error: AppErrorShape | null;
 29	} {
 30	  const [pending, setPending] = useState(false);
 31	  const [error, setError] = useState<AppErrorShape | null>(null);
 32	
 33	  // Callers pass an inline options object; a ref keeps `submit` stable so the
 34	  // form does not re-register its handler on every render.
 35	  const optionsRef = useRef(options);
 36	  useEffect(() => {
 37	    optionsRef.current = options;
 38	  }, [options]);
 39	
 40	  const submit = useCallback(
 41	    async (input: TInput): Promise<void> => {
 42	      const current = optionsRef.current;
 43	      setPending(true);
 44	      try {
 45	        const result = await action(input);
 46	        if (result.ok) {
 47	          if (current?.resetOnSuccess !== false) setError(null);
 48	          current?.onSuccess?.();
 49	        } else {
 50	          setError(result.error);
 51	          current?.onError?.(result.error);
 52	        }
 53	      } catch (thrown) {
 54	        const appError = toAppError(thrown);
 55	        setError(appError);
 56	        current?.onError?.(appError);
 57	      } finally {
 58	        setPending(false);
 59	      }
 60	    },
 61	    [action],
 62	  );
 63	
 64	  return { submit, pending, error };
 65	}
