 18	
 19	/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
 20	export class NotFoundError extends Error {
 21	  readonly code = "not_found" as const;
 22	
 23	  constructor(
 24	    readonly entity: string,
 25	    readonly id: string,
 26	  ) {
 27	    super(`${entity} ${id} was not found`);
 28	    this.name = "NotFoundError";
 29	  }
 30	}
 31	
 32	/** Unwraps a repository read, turning the `null` case into a domain error. */
 33	export function requireFound<T>(
 34	  value: T | null | undefined,
 35	  entity: string,
 36	  id: string,
 37	): T {
 38	  if (value === null || value === undefined) {
 39	    throw new NotFoundError(entity, id);
 40	  }
 41	  return value;
 42	}
 43	
 44	export function orgResource(orgId: OrgId): PermissionResource {
 45	  return { kind: "organization", orgId };
 46	}
 47	
 48	export function billingResource(orgId: OrgId): PermissionResource {
 49	  return { kind: "billing", orgId };
 50	}
